const recursiveDecomposition = async (task) => {
  const queen = await spawnQueen();
  const analysis = await queen.analyze(task);

  if (analysis.complexity > threshold) {
    // Spawn sub-queens for sub-problems
    const subQueens = await Promise.all(
      analysis.subProblems.map(sp => spawnSubQueen(sp))
