#### Day 13: Security Hardening
```typescript
// Security implementation
export class SecurityLayer {
  // 1. Command sanitization
  sanitizeCommand(cmd: string): string {
    return cmd
      .replace(/[;&|<>]/g, '') // Remove dangerous characters
      .slice(0, 1024); // Limit length
  }

  // 2. Rate limiting
  setupRateLimit() {
    return rateLimit({
      windowMs: 15 * 60 * 1000, // 15 minutes
      max: 100, // limit each IP to 100 requests per windowMs
      handler: (req, res) => {
        res.status(429).json({
          error: 'Too many requests'
        });
      }
    });
  }

  // 3. Authentication
  async authenticate(token: string): Promise<User> {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    return await this.userService.findById(decoded.userId);
  }

  // 4. Sandbox execution
  async executeSandboxed(cmd: string) {
    return await dockerode.run('sandbox-image', ['bash', '-c', cmd], {
      HostConfig: {
        Memory: 512 * 1024 * 1024, // 512MB limit
        CpuShares: 512,
        ReadonlyRootfs: true
      }
    });
  }
}
