### Countdown Timer Implementation
```typescript
async function displayCountdown(resumeTime: number): Promise<void> {
  const startTime = Date.now();
  const totalWait = resumeTime - startTime;

  const interval = setInterval(() => {
    const now = Date.now();
    const remaining = resumeTime - now;

    if (remaining <= 0) {
      clearInterval(interval);
      console.log('\n✅ Usage limit reset - resuming operation...');
      return;
    }

    const minutes = Math.floor(remaining / 60000);
    const seconds = Math.floor((remaining % 60000) / 1000);
    const progress = ((totalWait - remaining) / totalWait * 100).toFixed(1);

    process.stdout.write(`\r⏳ Waiting for usage limit reset: ${minutes}:${seconds.toString().padStart(2, '0')} [${progress}%]`);
  }, 1000);
}
