```javascript
class ConfigWatcher {
  constructor(configManager) {
    this.configManager = configManager;
    this.watcher = null;
    this.reloadTimeout = null;
  }

  start() {
    const configFiles = [
      path.join(CONFIG_DIR, 'settings.json'),
      path.join(CONFIG_DIR, 'mcp-servers.json')
    ];

    this.watcher = chokidar.watch(configFiles, {
      persistent: true,
      ignoreInitial: true,
      awaitWriteFinish: {
        stabilityThreshold: 500,
        pollInterval: 100
      }
    });

    this.watcher.on('change', this.handleChange.bind(this));
    this.watcher.on('error', this.handleError.bind(this));
  }

  handleChange(filepath) {
    // Debounce multiple changes
    clearTimeout(this.reloadTimeout);

    this.reloadTimeout = setTimeout(() => {
      console.log(`Config changed: ${path.basename(filepath)}`);
      this.configManager.reload()
        .then(() => console.log('Configuration reloaded successfully'))
        .catch(err => console.error('Failed to reload config:', err));
    }, 100);
  }

  stop() {
    if (this.watcher) {
      this.watcher.close();
    }
  }
}
```

