```typescript
function buildArgs(hookType: string, options: Record<string, any>): string[] {
  const args = [hookType];

  Object.entries(options).forEach(([key, value]) => {
    if (value !== undefined && value !== null) {
      // Handle parameter name mapping
      const flagName = mapParameterName(key);

      if (typeof value === 'boolean') {
        if (value) {
          args.push(`--${flagName}`);
        } else {
          args.push(`--no-${flagName}`);
        }
      } else {
        args.push(`--${flagName}`, String(value));
      }
    }
  });

  return args;
}

// NEW: Parameter name mapping function
function mapParameterName(key: string): string {
  const mappings: Record<string, string> = {
    'validateSafety': 'validate-safety',
    'prepareResources': 'prepare-resources',
    'autoAssignAgents': 'auto-assign-agents',
    'loadContext': 'load-context',
    'trackMetrics': 'track-metrics',
    'storeResults': 'store-results',
    'updateMemory': 'update-memory',
    'trainNeural': 'train-neural',
    'persistState': 'persist-state'
  };

  return mappings[key] || key.replace(/([A-Z])/g, '-$1').toLowerCase();
}
```

### Step 2.2: Update parseArgs Function
```typescript
function parseArgs<T extends BaseHookOptions>(args: string[]): T {
  const options: any = {};

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      const camelKey = mapFlagToCamelCase(key);

      if (args[i + 1] && !args[i + 1].startsWith('--')) {
        options[camelKey] = args[i + 1];
        i++; // Skip next argument
      } else {
        options[camelKey] = true;
      }
    }
  }

  return options as T;
}

// NEW: Flag to camelCase mapping
function mapFlagToCamelCase(flag: string): string {
  const mappings: Record<string, string> = {
    'validate-safety': 'validateSafety',
    'prepare-resources': 'prepareResources',
    'auto-assign-agents': 'autoAssignAgents',
    'load-context': 'loadContext',
    'track-metrics': 'trackMetrics',
    'store-results': 'storeResults',
    'update-memory': 'updateMemory',
    'train-neural': 'trainNeural',
    'persist-state': 'persistState'
  };

  return mappings[flag] || flag.replace(/-([a-z])/g, (_, letter) => letter.toUpperCase());
}
```

