async function generateHookHelpers(projectDir) {
  const helpersDir = path.join(projectDir, '.claude', 'helpers');
  await fs.mkdir(helpersDir, { recursive: true });

  for (const [filename, content] of Object.entries(HELPER_SCRIPTS)) {
