## Local Fix Implemented & Verified

While waiting for an upstream fix, we built a working `hook-handler.cjs` shim that resolves all three blocking errors. Sharing here in case it helps other users hitting the same issue.

### Fix: `.claude/helpers/hook-handler.cjs`

```javascript
#!/usr/bin/env node
/**
 * Claude Flow Hook Handler (local shim)
 *
 * Handles all hook subcommands referenced by .claude/settings.json:
 *   pre-bash, post-edit, route, session-restore, session-end, status
 *
 * This is a local shim that exits cleanly so hooks don't block Claude Code.
 * When claude-flow ships a real hook-handler.cjs (see #1107), this file can be replaced.
 *
 * IMPORTANT: Uses .cjs extension for CommonJS compat in ES module projects.
 */

/* eslint-disable @typescript-eslint/no-var-requires */
const fs = require('fs');
const path = require('path');

const PROJECT_ROOT = path.resolve(__dirname, '../..');
const LOG_DIR = path.join(PROJECT_ROOT, '.claude-flow', 'hooks');
const LOG_FILE = path.join(LOG_DIR, 'hook-events.jsonl');

try {
  if (!fs.existsSync(LOG_DIR)) fs.mkdirSync(LOG_DIR, { recursive: true });
} catch { /* best effort */ }

function logEvent(command, data) {
  try {
    const entry = JSON.stringify({ ts: new Date().toISOString(), cmd: command, ...data });
    fs.appendFileSync(LOG_FILE, entry + '\n');
  } catch { /* best effort */ }
}

function readStdin() {
  try {
    if (process.stdin.isTTY) return {};
    const input = fs.readFileSync('/dev/stdin', 'utf-8').trim();
    if (!input) return {};
    return JSON.parse(input);
  } catch { return {}; }
}

const handlers = {
  'pre-bash'(input) {
    logEvent('pre-bash', { command: input.command || input.tool_input?.command });
  },
  'post-edit'(input) {
    logEvent('post-edit', { file: input.filePath || input.tool_input?.file_path, tool: input.tool_name });
  },
  'route'(input) {
    logEvent('route', { promptLength: (input.prompt || '').length });
  },
  'session-restore'(input) {
    logEvent('session-restore', { event: input.event });
  },
  'session-end'(input) {
    logEvent('session-end', {});
  },
  'status'(input) {
    logEvent('status', { agent: input.agent_type });
  },
};

const command = process.argv[2];
if (!command) { console.error('Usage: hook-handler.cjs <subcommand>'); process.exit(1); }
const handler = handlers[command];
if (!handler) { logEvent('unknown', { command }); process.exit(0); }
const input = readStdin();
handler(input);
process.exit(0);
```

