### Suggested upstream fix

Ideally `hooks init` (or MCP setup) should generate this file automatically. The scaffolded `.claude/settings.json` references `hook-handler.cjs` in 6 places but never creates it. Either:

1. **Ship `hook-handler.cjs` during `hooks init`** with real implementations that persist to AgentDB (fixing #1058 simultaneously)
2. **At minimum, add `"continueOnError": true`** to `PreToolUse`, `PostToolUse`, and `UserPromptSubmit` hooks in the scaffolded config so missing handlers degrade gracefully instead of hard-blocking

I reverse-engineered it from the codex implementation and the docs. This should work with persistence until they fix the issue:
```#!/usr/bin/env node
/**
 * Claude Flow Hook Handler
 *
 * Provides resilient hook dispatch plus persistence into:
 * - AgentDB memory_entries (preferred; .swarm/memory.db by default)
 * - local session + JSON files as fallback/auxiliary logs
 */

const fs = require('fs');
const path = require('path');

const PROJECT_ROOT = path.resolve(__dirname, '../..');
const FLOW_DIR = path.join(PROJECT_ROOT, '.claude-flow');
const LOG_DIR = path.join(FLOW_DIR, 'hooks');
const LOG_FILE = path.join(LOG_DIR, 'hook-events.jsonl');
const SESSION_DIR = path.join(FLOW_DIR, 'sessions');
const SESSION_FILE = path.join(SESSION_DIR, 'current.json');
const MEMORY_DIR = path.join(FLOW_DIR, 'data');
const MEMORY_FILE = path.join(MEMORY_DIR, 'memory.json');

const AGENT_DB_CANDIDATES = [
  process.env.CLAUDE_FLOW_MEMORY_DB ? path.resolve(PROJECT_ROOT, process.env.CLAUDE_FLOW_MEMORY_DB) : null,
  path.join(PROJECT_ROOT, '.swarm', 'memory.db'),
  path.join(PROJECT_ROOT, '.claude-flow', 'memory.db'),
  path.join(PROJECT_ROOT, '.agentdb', 'memory.db'),
  path.join(PROJECT_ROOT, 'memory.db'),
].filter(Boolean);

// --- Utilities ---

function ensureDir(dir) {
  try { if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true }); } catch {}
}

function nowSec() {
  return Math.floor(Date.now() / 1000);
}

function safeParseJSON(value, fallback) {
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

function toJSONString(value, fallback = '{}') {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value);
  } catch {
    return fallback;
  }
}

function shortText(input, max = 800) {
  if (typeof input !== 'string') return '';
  return input.length > max ? `${input.slice(0, max)}...` : input;
}

function logEvent(cmd, data) {
  try {
    ensureDir(LOG_DIR);
    fs.appendFileSync(LOG_FILE, JSON.stringify({ ts: new Date().toISOString(), cmd, ...data }) + '\n');
  } catch {}
}

function readStdin() {
  try {
    if (process.stdin.isTTY) return {};
    const input = fs.readFileSync('/dev/stdin', 'utf-8').trim();
    return input ? JSON.parse(input) : {};
  } catch {
    return {};
  }
}

// --- Session (inlined from session.js) ---

function loadSession() {
  try { return JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8')); } catch { return null; }
}

function saveSession(session) {
  ensureDir(SESSION_DIR);
  fs.writeFileSync(SESSION_FILE, JSON.stringify(session, null, 2));
}

function sessionStart() {
  const session = {
    id: `session-${Date.now()}`,
    startedAt: new Date().toISOString(),
    cwd: PROJECT_ROOT,
    context: {},
    metrics: { edits: 0, commands: 0, tasks: 0, errors: 0 },
  };
  saveSession(session);
  return session;
}

function sessionRestore() {
  const session = loadSession();
  if (session) {
    session.restoredAt = new Date().toISOString();
    saveSession(session);
    return session;
  }
  return sessionStart();
}

function sessionEnd() {
  const session = loadSession();
  if (!session) return null;
  session.endedAt = new Date().toISOString();
  session.duration = Date.now() - new Date(session.startedAt).getTime();
  ensureDir(SESSION_DIR);
  fs.writeFileSync(path.join(SESSION_DIR, `${session.id}.json`), JSON.stringify(session, null, 2));
  try { fs.unlinkSync(SESSION_FILE); } catch {}
  return session;
}

function sessionStatus() {
  return loadSession();
}

function sessionMetric(name) {
  const session = loadSession();
  if (session && session.metrics[name] !== undefined) {
    session.metrics[name] += 1;
    saveSession(session);
  }
}

// --- Local JSON memory (fallback + compatibility) ---

function loadMemory() {
  try { return JSON.parse(fs.readFileSync(MEMORY_FILE, 'utf-8')); } catch { return {}; }
}

function saveMemory(mem) {
  ensureDir(MEMORY_DIR);
  fs.writeFileSync(MEMORY_FILE, JSON.stringify(mem, null, 2));
}

function memorySet(key, value) {
  const mem = loadMemory();
  mem[key] = value;
  mem._updated = new Date().toISOString();
  saveMemory(mem);
}

// --- Router (inlined from router.js) ---

const TASK_PATTERNS = {
  'implement|create|build|add|write code': 'coder',
  'test|spec|coverage|unit test|integration': 'tester',
  'review|audit|check|validate|security': 'reviewer',
  'research|find|search|documentation|explore': 'researcher',
  'design|architect|structure|plan': 'architect',
  'api|endpoint|server|backend|database': 'backend-dev',
  'ui|frontend|component|react|css|style': 'frontend-dev',
  'deploy|docker|ci|cd|pipeline|infrastructure': 'devops',
};

function routeTask(task) {
  const lower = task.toLowerCase();
  for (const [pattern, agent] of Object.entries(TASK_PATTERNS)) {
    if (new RegExp(pattern, 'i').test(lower)) {
      return { agent, confidence: 0.8, reason: `Matched pattern: ${pattern}` };
    }
  }
  return { agent: 'coder', confidence: 0.5, reason: 'Default routing - no specific pattern matched' };
}

// --- AgentDB persistence ---

function resolveAgentDbPath() {
  const existing = AGENT_DB_CANDIDATES.find((candidate) => fs.existsSync(candidate));
  return existing || AGENT_DB_CANDIDATES[0];
}

function loadAgentDbModule() {
  try {
    return require('agentdb');
  } catch {
    try {
      return require(path.join(PROJECT_ROOT, 'node_modules', 'agentdb'));
    } catch {
      return null;
    }
  }
}

function ensureMemoryEntriesSchema(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS memory_entries (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      key TEXT NOT NULL,
      value TEXT NOT NULL,
      namespace TEXT NOT NULL DEFAULT 'default',
      metadata TEXT,
      created_at INTEGER DEFAULT (strftime('%s', 'now')),
      updated_at INTEGER DEFAULT (strftime('%s', 'now')),
      accessed_at INTEGER DEFAULT (strftime('%s', 'now')),
      access_count INTEGER DEFAULT 0,
      ttl INTEGER,
      expires_at INTEGER,
      content TEXT DEFAULT '',
      type TEXT DEFAULT 'semantic',
      embedding TEXT,
      embedding_model TEXT DEFAULT 'local',
      embedding_dimensions INTEGER,
      tags TEXT,
      owner_id TEXT,
      last_accessed_at INTEGER,
      status TEXT DEFAULT 'active',
      UNIQUE(key, namespace)
    );
  `);
  db.exec('CREATE INDEX IF NOT EXISTS idx_memory_namespace ON memory_entries(namespace);');
  db.exec('CREATE INDEX IF NOT EXISTS idx_memory_accessed ON memory_entries(accessed_at);');
}

async function openAgentDb() {
  const agentdb = loadAgentDbModule();
  if (!agentdb || typeof agentdb.createDatabase !== 'function') return null;

  const dbPath = resolveAgentDbPath();
  try {
    ensureDir(path.dirname(dbPath));

    // Suppress init logs from agentdb so hooks stay silent.
    const originalLog = console.log;
    const originalWarn = console.warn;
    console.log = () => {};
    console.warn = () => {};

    try {
      const db = await agentdb.createDatabase(dbPath);
      ensureMemoryEntriesSchema(db);
      return { db, dbPath };
    } finally {
      console.log = originalLog;
      console.warn = originalWarn;
    }
  } catch {
    return null;
  }
}

function dbReadJSONEntry(db, key, namespace, fallback = null) {
  try {
    const row = db.prepare(
      'SELECT value FROM memory_entries WHERE key = ? AND namespace = ? LIMIT 1'
    ).get(key, namespace);
    if (!row || typeof row.value !== 'string') return fallback;
    return safeParseJSON(row.value, fallback);
  } catch {
    return fallback;
  }
}

function dbUpsertEntry(db, opts) {
  const key = opts.key;
  const namespace = opts.namespace || 'default';
  const value = toJSONString(opts.value, '{}');
  const metadata = toJSONString(opts.metadata || {}, '{}');
  const tags = Array.isArray(opts.tags) ? JSON.stringify(opts.tags) : null;
  const content = shortText(opts.content || value, 1200);
  const type = opts.type || 'semantic';
  const ts = nowSec();

  db.prepare(`
    INSERT INTO memory_entries (
      key, value, namespace, metadata, created_at, updated_at, accessed_at, access_count,
      content, type, tags, last_accessed_at, status
    ) VALUES (
      ?, ?, ?, ?, ?, ?, ?, 1,
      ?, ?, ?, ?, 'active'
    )
    ON CONFLICT(key, namespace) DO UPDATE SET
      value = excluded.value,
      metadata = excluded.metadata,
      updated_at = excluded.updated_at,
      accessed_at = excluded.accessed_at,
      access_count = COALESCE(memory_entries.access_count, 0) + 1,
      content = excluded.content,
      type = excluded.type,
      tags = excluded.tags,
      last_accessed_at = excluded.last_accessed_at,
      status = 'active'
  `).run(key, value, namespace, metadata, ts, ts, ts, content, type, tags, ts);
}

function dbUpsertSessionState(db, sessionId, updateFn) {
  if (!sessionId) return;

  const key = `session-state:${sessionId}`;
  const namespace = 'session-states';
  const current = dbReadJSONEntry(db, key, namespace, {
    sessionId,
    tasks: [],
    edits: [],
    commands: [],
    agents: [],
  });

  const nextState = updateFn ? updateFn(current) || current : current;
  nextState.sessionId = sessionId;
  nextState.persistedAt = new Date().toISOString();
  nextState.fullState = true;

  dbUpsertEntry(db, {
    key,
    namespace,
    value: nextState,
    metadata: { type: 'full-state', sessionId },
    tags: ['session', 'state'],
  });
}

function dbUpsertSessionMetrics(db, session) {
  if (!session || !session.id) return;

  const duration = Number.isFinite(session.duration)
    ? session.duration
    : Math.max(0, Date.now() - new Date(session.startedAt).getTime());
  const minutes = duration > 0 ? duration / 60000 : 0;
  const metrics = session.metrics || {};

  const payload = {
    sessionDuration: duration,
    sessionDurationHuman: `${minutes.toFixed(2)} minutes`,
    totalTasks: metrics.tasks || 0,
    totalEdits: metrics.edits || 0,
    totalCommands: metrics.commands || 0,
    uniqueAgents: 0,
    commandSuccessRate: 100,
    avgTasksPerMinute: minutes > 0 ? (metrics.tasks || 0) / minutes : 0,
    avgEditsPerMinute: minutes > 0 ? (metrics.edits || 0) / minutes : 0,
    timestamp: new Date().toISOString(),
  };

  dbUpsertEntry(db, {
    key: `session-metrics:${session.id}`,
    namespace: 'session-metrics',
    value: payload,
    metadata: { type: 'performance-metrics', sessionId: session.id },
    tags: ['session', 'metrics'],
  });
}

function dbUpsertSessionSummary(db, session, hookType) {
  if (!session || !session.id) return;

  const payload = {
    sessionId: session.id,
    startedAt: session.startedAt,
    restoredAt: session.restoredAt,
    endedAt: session.endedAt,
    totalTasks: session.metrics?.tasks || 0,
    totalEdits: session.metrics?.edits || 0,
    totalCommands: session.metrics?.commands || 0,
    metrics: session.metrics || {},
    hookType,
  };

  dbUpsertEntry(db, {
    key: `session:${session.id}`,
    namespace: 'sessions',
    value: payload,
    metadata: { hookType },
    tags: ['session'],
  });
}

function dbStoreHookEvent(db, command, payload, sessionId) {
  const ts = Date.now();
  const key = `hook:${command}:${ts}`;
  dbUpsertEntry(db, {
    key,
    namespace: 'hook-events',
    value: {
      ts: new Date(ts).toISOString(),
      command,
      sessionId: sessionId || null,
      ...payload,
    },
    metadata: { source: 'hook-handler', command },
    content: `${command} ${payload && payload.file ? payload.file : payload && payload.command ? payload.command : ''}`.trim(),
    type: 'episodic',
    tags: ['hook', command],
  });
}

function dbStoreEditPattern(db, filePath) {
  if (!filePath) return;
  const ext = path.extname(filePath) || 'unknown';
  const dir = path.dirname(filePath);
  const key = `edit-pattern:${ext}`;
  const namespace = 'patterns';
  const existing = dbReadJSONEntry(db, key, namespace, null);

  const pattern = existing && typeof existing === 'object'
    ? existing
    : { ext, count: 0, createdAt: new Date().toISOString() };

  pattern.count = (pattern.count || 0) + 1;
  pattern.lastFile = filePath;
  pattern.lastDir = dir;
  pattern.updatedAt = new Date().toISOString();

  dbUpsertEntry(db, {
    key,
    namespace,
    value: pattern,
    metadata: { type: 'edit-pattern', extension: ext },
    tags: ['pattern', 'edit', ext],
  });
}

function dbStoreRouteDecision(db, prompt, routeResult, sessionId) {
  if (!prompt || !routeResult) return;
  const key = `route:${sessionId || 'no-session'}:${Date.now()}`;
  dbUpsertEntry(db, {
    key,
    namespace: 'routing',
    value: {
      prompt: shortText(prompt, 1200),
      promptLength: prompt.length,
      route: routeResult,
      timestamp: new Date().toISOString(),
      sessionId: sessionId || null,
    },
    metadata: { type: 'route-decision', sessionId: sessionId || null },
    content: `route -> ${routeResult.agent} (${routeResult.confidence})`,
    type: 'procedural',
    tags: ['route', routeResult.agent],
  });
}

async function withAgentDb(work) {
  const opened = await openAgentDb();
  if (!opened) return;
  try {
    await work(opened.db, opened.dbPath);
  } catch (error) {
    logEvent('agentdb-error', { error: error && error.message ? error.message : 'unknown' });
  } finally {
    try { opened.db.close(); } catch {}
  }
}

// --- Handlers ---

const handlers = {
  async 'pre-bash'(input) {
    const command = input.tool_input?.command || input.command || '';
    const session = loadSession();

    logEvent('pre-bash', { command, sessionId: session?.id || null });
    try { sessionMetric('commands'); } catch {}

    await withAgentDb(async (db) => {
      const freshSession = loadSession();
      dbStoreHookEvent(db, 'pre-bash', { command }, freshSession?.id);
      if (freshSession?.id) {
        dbUpsertSessionState(db, freshSession.id, (state) => {
          const commands = Array.isArray(state.commands) ? state.commands : [];
          commands.push({ command: shortText(command, 600), at: new Date().toISOString() });
          state.commands = commands.slice(-200);
          return state;
        });
        dbUpsertSessionMetrics(db, freshSession);
        dbUpsertSessionSummary(db, freshSession, 'pre-bash');
      }
    });
  },

  async 'post-edit'(input) {
    const filePath = input.tool_input?.file_path || input.tool_input?.path || input.filePath || '';
    const toolName = input.tool_name || 'unknown';
    const session = loadSession();

    logEvent('post-edit', { file: filePath, tool: toolName, sessionId: session?.id || null });
    try { sessionMetric('edits'); } catch {}

    // Keep local JSON fallback in sync.
    if (filePath) {
      try {
        const ext = path.extname(filePath);
        const dir = path.dirname(filePath);
        const key = `edit-pattern-${ext || 'unknown'}`;
        const mem = loadMemory();
        const existing = typeof mem[key] === 'object' && mem[key] !== null ? mem[key] : null;

        if (existing) {
          existing.count = (existing.count || 0) + 1;
          existing.lastFile = filePath;
          existing.lastDir = dir;
          existing.updatedAt = new Date().toISOString();
          memorySet(key, existing);
        } else {
          memorySet(key, {
            ext,
            count: 1,
            lastFile: filePath,
            lastDir: dir,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
          });
        }
      } catch {}
