    $backup = "$Path.backup.$ts"
    Copy-Item -LiteralPath $Path -Destination $backup -Force
    Write-Ok "✓ Backed up to: $backup"
  }
}

function Remove-LinesMatching([string]$Path, [string[]]$Patterns) {
  if (!(Test-Path -LiteralPath $Path -PathType Leaf)) { return }
  $content = Get-Content -LiteralPath $Path -Raw
  $lines = $content -split "(`r`n|`n|`r)"
  $filtered = $lines | Where-Object {
    $line = $_
    $keep = $true
    foreach ($p in $Patterns) {
      if ($line -match $p) { $keep = $false; break }
    }
    $keep
  }
  # Preserve original newline style as best as possible
  $out = ($filtered -join "`r`n")
  Set-Content -LiteralPath $Path -Value $out -Encoding UTF8
}

function Expand-PathSafe([string]$p) {
  if ([string]::IsNullOrWhiteSpace($p)) { return $p }
  # Support ~
  if ($p.StartsWith("~")) {
    $p = $p -replace "^~", $HOME
  }
  # Expand env vars like %APPDATA% if present
  return [Environment]::ExpandEnvironmentVariables($p)
}

