function Clean-ClaudeSettingsJson([string]$Path) {
  if (!(Test-Path -LiteralPath $Path -PathType Leaf)) {
    Write-Warn "⚠ Claude Code settings not found: $Path"
    return
  }

  Backup-File $Path
  Write-Host "Surgically removing ONLY claude-flow hooks and settings..."

  try {
    $json = Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json

    # Remove env entries starting with CLAUDE_FLOW_
    if ($null -ne $json.env) {
      $newEnv = [ordered]@{}
      foreach ($p in $json.env.PSObject.Properties) {
        if (-not $p.Name.StartsWith("CLAUDE_FLOW_")) {
          $newEnv[$p.Name] = $p.Value
        }
      }
      $json.env = $newEnv
    }

    # Remove claude-flow / ruv-swarm / flow-nexus from enabledMcpjsonServers
