      $json.enabledMcpjsonServers = @($json.enabledMcpjsonServers | Where-Object {
        $_ -ne "claude-flow" -and $_ -ne "ruv-swarm" -and $_ -ne "flow-nexus"
      })
    }

    # Surgical hook removal: remove any hook command containing claude-flow/ruv-swarm/flow-nexus
    if ($null -ne $json.hooks) {
      $hookKeys = @("PreToolUse","PostToolUse","Stop","PreCompact")
      foreach ($hk in $hookKeys) {
        if ($null -ne $json.hooks.$hk) {
          $cleanedGroups = @()
          foreach ($group in $json.hooks.$hk) {
            if ($null -ne $group.hooks) {
              $group.hooks = @($group.hooks | Where-Object {
                $cmd = $_.command
                if ($null -eq $cmd) { return $true }
                ($cmd -notmatch "claude-flow") -and ($cmd -notmatch "ruv-swarm") -and ($cmd -notmatch "flow-nexus")
              })
              # Keep group if hooks exist or if hooks field absent
              if (($null -ne $group.hooks -and $group.hooks.Count -gt 0) -or ($null -eq $group.hooks)) {
                $cleanedGroups += $group
              }
            } else {
              $cleanedGroups += $group
            }
          }
          $json.hooks.$hk = $cleanedGroups
        }
      }
    }

    # Write back
    $jsonOut = $json | ConvertTo-Json -Depth 50
    Set-Content -LiteralPath $Path -Value $jsonOut -Encoding UTF8
    Write-Ok "✓ Surgically cleaned Claude Code settings (JSON-aware)"
  } catch {
    Write-Warn "⚠ JSON parse/edit failed, falling back to line-based removal..."
    $patterns = @("claude-flow","ruv-swarm","flow-nexus","CLAUDE_FLOW_")
    Remove-LinesMatching $Path $patterns
    Write-Ok "✓ Cleaned Claude Code settings (line-based)"
  }
}

